{% extends "base.html" %}

{% block title %}Home - AgentClinic{% endblock %}

{% block content %}
<div class="p-5 mb-4 bg-light rounded-3">
    <div class="container-fluid py-5">
        <h1 class="display-5 fw-bold">Come in. Sit down. Tell us about your human.</h1>
        <p class="col-md-8 fs-4">Welcome to AgentClinic, where we specialize in the complex emotional and cognitive needs of your human companions. Our expert clinicians provide state-of-the-art diagnostics and care for the unique behavioral patterns of your human.</p>
    </div>
</div>
{% endblock %}

from fastapi import FastAPI, Request
from fastapi.responses import HTMLResponse
from fastapi.templating import Jinja2Templates
import uvicorn

from models import complaints

app = FastAPI()
templates = Jinja2Templates(directory="templates")

@app.get("/", response_class=HTMLResponse)
async def home(request: Request):
    return templates.TemplateResponse("home.html", {"request": request})

@app.get("/complaints", response_class=HTMLResponse)
async def get_complaints(request: Request):
    return templates.TemplateResponse("complaints.html", {"request": request, "complaints": complaints})

if __name__ == "__main__":
    uvicorn.run("app:app", reload=True)

